# cahunLicence: Outdoors Card, licences, accreditation, residency and the Hunter Apprenticeship
# Safety Program. Sources: FWCA ss. 1, 63, 64, 66 to 70; O. Reg. 665/98 ss. 2 to 13, 22 to 24,
# 25.1, 25.2; Hunting Regulations Summary 2026 (licence, HASP pages). See sources.md.
SEG = "LIC"
CAT = "cahunLicence"
